'use server';

import {
  GRAMPEADOR_MODEL,
  GRAMPEADOR_OPTIONS,
  buildGrampeadorPrompt,
} from '@/app/config/grampeador';
import { assertDomainAccess, requireCurrentUser } from '@/app/lib/auth-session';

const OLLAMA_BASE_URL = process.env.OLLAMA_BASE_URL || 'http://host.docker.internal:11434';

/**
 * Grampeador bubbles are generated by a local Ollama model. Units without
 * Ollama (docker-compose.no-ollama.yml) set GRAMPEADOR_ENABLED=false so the
 * Hub shows static phrases and never calls Ollama.
 */
export async function isGrampeadorEnabled(): Promise<boolean> {
  return process.env.GRAMPEADOR_ENABLED?.trim().toLowerCase() !== 'false';
}

// Ollama failures are logged once per process; the UI falls back to static
// phrases, so repeating the warning every minute per open tab is just noise.
let ollamaFailureLogged = false;

function warnOllamaFailureOnce(detail: string): void {
  if (ollamaFailureLogged) return;
  ollamaFailureLogged = true;
  console.warn(`[Grampeador] Ollama unavailable (${detail}); using static bubbles. Further failures are not logged. Set GRAMPEADOR_ENABLED=false to disable.`);
}

const TIME_LABEL: Record<string, (h: number) => string> = {
  pt: h => h < 6 ? 'madrugada' : h < 12 ? 'manhã' : h < 18 ? 'tarde' : 'noite',
  en: h => h < 6 ? 'night'     : h < 12 ? 'morning' : h < 18 ? 'afternoon' : 'evening',
  es: h => h < 6 ? 'madrugada' : h < 12 ? 'mañana'  : h < 18 ? 'tarde' : 'noche',
  ca: h => h < 6 ? 'matinada'  : h < 12 ? 'matí'    : h < 18 ? 'tarda' : 'nit',
};

const FORBIDDEN_RE = /^(aqui vai|here you go|aquí va|here|olha|look|sure|claro|veja|mira|vinga|clar)[:\s!]*/i;

function sanitize(raw: string): string {
  return raw
    .replace(FORBIDDEN_RE, '')
    .replace(/^["'"'«»]|["'"'»]$/g, '')
    .trim();
}

export async function generateClippyBubble(domain: string, locale = 'pt'): Promise<string | null> {
  const user = await requireCurrentUser();
  if (!/^[a-z0-9][a-z0-9_-]{0,49}$/.test(domain)) return null;
  await assertDomainAccess(user, domain);
  if (!(await isGrampeadorEnabled())) return null;
  if (!Object.hasOwn(TIME_LABEL, locale)) locale = 'en';

  const hour = new Date().getHours();
  const timeFn = TIME_LABEL[locale] ?? TIME_LABEL['en'];
  const timeLabel = timeFn(hour);
  const prompt = buildGrampeadorPrompt(domain, timeLabel, locale);

  console.log(`[Grampeador] Generating for domain="${domain}" locale="${locale}" ${hour}h (${timeLabel})`);

  try {
    const res = await fetch(`${OLLAMA_BASE_URL}/api/generate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: GRAMPEADOR_MODEL,
        prompt,
        stream: false,
        options: GRAMPEADOR_OPTIONS,
      }),
      signal: AbortSignal.timeout(8000),
    });

    if (!res.ok) {
      warnOllamaFailureOnce(`HTTP ${res.status}`);
      return null;
    }

    const data = await res.json();
    const raw = (data.response as string | undefined)?.trim() ?? '';
    const text = sanitize(raw);

    console.log(`[Grampeador] Generated: "${text}"`);
    return text || null;
  } catch (err) {
    warnOllamaFailureOnce(err instanceof Error ? err.message : String(err));
    return null;
  }
}
